//源表：card_option.xlsx（卡牌掉落内容表）
#pragma warning disable 8981

using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<int, card_option> card_optionData;
        public card_option Getcard_optionConfig(int key)
        {
            return ConfigBinary.Require(card_optionData, key, "card_option");
        }
        private void Loadcard_optionConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("card_option"))
            {
                int count = r.ReadInt32();
                card_optionData = new Dictionary<int, card_option>(count);
                for (int i = 0; i < count; i++)
                {
                    card_option row;
                    row.key = r.ReadInt32();
                    row.title = ConfigBinary.ReadString(r);
                    row.description = ConfigBinary.ReadString(r);
                    row.weight = r.ReadInt32();
                    row.silver.a = r.ReadInt32();
                    row.silver.b = r.ReadInt32();
                    row.gold.a = r.ReadInt32();
                    row.gold.b = r.ReadInt32();
                    row.holo.a = r.ReadInt32();
                    row.holo.b = r.ReadInt32();
                    byte has6 = r.ReadByte();
                    row.camp = has6 == 1 ? (int?)(r.ReadInt32()) : null;
                    row.type = ConfigBinary.ReadString(r);
                    row.value = r.ReadInt32();
                    card_optionData.Add(row.key, row);
                }
            }
        }
    }
    public struct card_option
    {
        public int key;  // 主键
        public string title;  // 标题
        public string description;  // 描述
        public int weight;  // 权重
        public Vector2Int silver;  // 白银卡可掉落幸运值
        public Vector2Int gold;  // 黄金卡有效幸运值
        public Vector2Int holo;  // 炫彩卡有效幸运值
        public int? camp;  // 阵营限制（空=无限制，0=仅限进攻方，1=仅限防守方）
        public string type;  // 类型（代码用）
        public int value;  // 值（可选，代码用）
    }
}
